package net.neoforged.neoforge.network.event;
import java.util.function.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;public class RegisterPayloadHandlersEvent {public final Registrar handler=new Registrar();public Registrar registrar(String version){return handler;}public static class Context {private final net.minecraft.world.entity.player.Player p;public Context(net.minecraft.world.entity.player.Player value){p=value;}public net.minecraft.world.entity.player.Player player(){return p;}}public static class Registrar {public Object type;public BiConsumer<Object,Context> receiver;public <T> Registrar playToServer(CustomPacketPayload.Type<T> t,StreamCodec<RegistryFriendlyByteBuf,T> codec,BiConsumer<T,Context> recv){type=t;receiver=(BiConsumer)recv;return this;}}}
